import{_ as t,o,c as i,a5 as l}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-15-apply-watermark/report3_spec.md","filePath":"feature/content-task-workflow/3-6-15-apply-watermark/report3_spec.md"}'),a={name:"feature/content-task-workflow/3-6-15-apply-watermark/report3_spec.md"};function r(n,e,s,p,d,c){return o(),i("div",null,[...e[0]||(e[0]=[l('<p><strong>3.6.15 Apply Watermark</strong></p><p><strong>Function Trigger</strong></p><p>A Creator opens the watermark tool embedded in a Task Detail (type Post), after a material has already been retouched.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Creator.</li><li><strong>Purpose</strong>: Let a Creator stamp a brand watermark (a Client-supplied logo) onto a finished image before publishing, similar to img2go, so the publication carries visible attribution/copyright marking.</li><li><strong>Interface</strong>: A watermark tool embedded in Task Detail with a live preview before applying.</li><li><strong>Data Processing</strong>: The system takes an already-retouched material plus a logo chosen from the Client&#39;s Brand Collection, composites them at a chosen position/opacity, and outputs a new file (never overwriting the original).</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Apply Watermark Tool:</p><ul><li>Image preview panel showing the retouched material with the watermark overlaid live.</li><li>Logo picker sourced from the Client&#39;s Brand Collection.</li><li>Position and opacity controls.</li><li>Apply / Cancel actions.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: <code>materialId</code> (the retouched image), <code>logoAssetId</code> (from the Client&#39;s Brand Collection), <code>position</code>, <code>opacity</code>.</li><li><strong>Input optional</strong>: none beyond position/opacity tuning.</li><li><strong>System data</strong>: the material record and the Client&#39;s Brand Collection logo assets.</li><li><strong>Output</strong>: <code>{id, url}</code> of the newly generated watermarked file.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>The watermarked output is a new file — the original image is never overwritten.</li><li>Only images are in scope (video watermarking is out of scope, same as img2go).</li></ul></li><li><p><strong>Validation</strong></p><ul><li><code>logoAssetId</code> not found in the Client&#39;s Brand Collection → 400 <code>LOGO_NOT_FOUND</code>.</li><li>Client&#39;s Brand Collection has no logo at all → the tool blocks apply and tells the user to upload a logo first, rather than allowing an empty watermark.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>A Creator opens the watermark tool from a Task Detail (Post) after retouching.</li></ol></li><li><ol start="2"><li>The Creator picks a logo from the Client&#39;s Brand Collection and adjusts position/opacity, previewing the result.</li></ol></li><li><ol start="3"><li>The system applies the watermark and outputs a new file, leaving the original untouched.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Chosen <code>logoAssetId</code> doesn&#39;t exist in the Brand Collection → 400 <code>LOGO_NOT_FOUND</code>.</li><li>2.b1: Client&#39;s Brand Collection is empty → the tool warns the Creator to have the Client upload a logo first, blocking an empty-watermark apply.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A new watermarked file is created and linked to the material/Task, with the original image left unmodified.</li></ul>',14)])])}const m=t(a,[["render",r]]);export{u as __pageData,m as default};
